     <a class="skip-link" href="#main-content">Skip to main content</a>

     <main id="main-content">
       <section class="support-card" aria-labelledby="support-title">
         <p class="eyebrow">Support</p>
         <h1 id="support-title">Contact our team</h1>
         <p class="intro">
           Tell us how to reach you and a support specialist will follow up as soon as possible.
         </p>
         <p class="required-note"><span aria-hidden="true">*</span> Required field</p>

         <form id="support-form" novalidate>
           <div class="form-field">
             <label for="full-name">
               Full name <span class="required-marker" aria-hidden="true">*</span>
             </label>
             <input
               id="full-name"
               name="full-name"
               type="text"
               autocomplete="name"
               required
               placeholder="Alex Morgan"
             >
             <p class="error-message" id="full-name-error" hidden>Error: Enter your full name.</p>
           </div>

           <div class="form-field">
             <label for="email">
               Email address <span class="required-marker" aria-hidden="true">*</span>
             </label>
             <input
               id="email"
               name="email"
               type="email"
               autocomplete="email"
               required
               placeholder="alex@example.com"
             >
             <p class="error-message" id="email-error" hidden>
               Error: Enter a valid email address, such as alex@example.com.
             </p>
           </div>

           <div class="form-field">
             <label for="phone">Phone number <span aria-hidden="true">(optional)</span></label>
             <input
               id="phone"
               name="phone"
               type="tel"
               autocomplete="tel"
               inputmode="tel"
               aria-describedby="phone-help"
               placeholder="(555) 123-4567"
             >
             <p class="helper-text" id="phone-help">
               Use a 10-digit phone number, such as (555) 123-4567.
             </p>
           </div>

           <div class="actions">
             <button type="submit">Send support request</button>
           </div>

           <p class="form-status" id="form-status" aria-live="polite"></p>
         </form>
       </section>
     </main>

     <script>
       const form = document.querySelector("#support-form");
       const statusMessage = document.querySelector("#form-status");
       const fields = [
         {
           input: document.querySelector("#full-name"),
           error: document.querySelector("#full-name-error"),
           isValid: (value) => value.trim().length > 0
         },
         {
           input: document.querySelector("#email"),
           error: document.querySelector("#email-error"),
           isValid: (value, input) => value.trim().length > 0 && input.validity.valid
         }
       ];

       function setFieldValidity(field, isValid) {
         if (isValid) {
           field.input.removeAttribute("aria-invalid");
           field.input.removeAttribute("aria-errormessage");
           field.error.hidden = true;
           return;
         }

         field.input.setAttribute("aria-invalid", "true");
         field.input.setAttribute("aria-errormessage", field.error.id);
         field.error.hidden = false;
       }

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         statusMessage.textContent = "";

         const invalidField = fields.find((field) => {
           const valid = field.isValid(field.input.value, field.input);
           setFieldValidity(field, valid);
           return !valid;
         });

         fields.forEach((field) => {
           if (field !== invalidField) {
             setFieldValidity(field, field.isValid(field.input.value, field.input));
           }
         });

         if (invalidField) {
           invalidField.input.focus();
           return;
         }

         statusMessage.textContent = "Thanks. Your support request is ready to send.";
         form.reset();
       });

       fields.forEach((field) => {
         field.input.addEventListener("input", () => {
           if (field.input.hasAttribute("aria-invalid")) {
             setFieldValidity(field, field.isValid(field.input.value, field.input));
           }
           statusMessage.textContent = "";
         });
       });
     </script>
   </body>
 </html>

